package net.minecraft.server.level;import java.util.*;public class ServerPlayer extends net.minecraft.world.entity.player.Player {public UUID uuid=UUID.randomUUID();public net.minecraft.server.MinecraftServer server;public int permission;public double x,y,z;public Inventory inventory=new Inventory();public ServerPlayer(net.minecraft.server.MinecraftServer s){server=s;s.online.put(uuid,this);}public net.minecraft.server.MinecraftServer getServer(){return server;}public UUID getUUID(){return uuid;}public boolean hasPermissions(int n){return permission>=n;}public double getX(){return x;}public double getY(){return y;}public double getZ(){return z;}public Profile getGameProfile(){return new Profile(uuid.toString().substring(0,6));}public Level level(){return new Level();}public Inventory getInventory(){return inventory;}public record Profile(String name){public String getName(){return name;}}public static class Level{public Dimension dimension(){return new Dimension();}}public static class Dimension{public net.minecraft.resources.ResourceLocation location(){return net.minecraft.resources.ResourceLocation.fromNamespaceAndPath("minecraft","overworld");}}public static class Inventory{public int capacity=100000,received;public boolean add(net.minecraft.world.item.ItemStack stack){int given=Math.min(capacity,stack.count);capacity-=given;received+=given;stack.count-=given;return stack.count==0;}}}